// Generated by `just generate` from `src/plugins/dotclaude/slices/decide/lab/second-opinion.test.ts`. Edit the source and run `just generate`.
// The hook lab of the `decide` slice: `claude plugin test plugins/dotclaude` runs the tool `second_opinion` with stubs.
// The key is set to an empty value, so Jev is not tried, and no network call goes out.
// The stub of `model.complete` answers for the fallback model, and it records the request that the fallback gets.

import type { ModelCompleteResult, On } from "claude-code";
import { type Engine, expect, mock, test } from "claude-code/testing";

// The input of the tool, for the typed `$.tool.call` of this test.
// A declaration in the author's project adds the MCP tool to `McpToolInputs`.
declare module "claude-code" {
  interface McpToolInputs {
    mcp__dotclaude__second_opinion: { question: string };
  }
}

const NO_USAGE = {
  input_tokens: 0,
  output_tokens: 0,
  cache_read_input_tokens: 0,
  cache_creation_input_tokens: 0,
};

/** Stubs for one test: the reply of the fallback model, and the list of the requests it gets. */
const stub = (on: On, seen: string[], answer: string | null): void => {
  mock.env(on, { TYPESAFE_API_KEY: "" });
  const reply: ModelCompleteResult =
    answer === null
      ? {
          isAnswered: false,
          reason: "api-error",
          status: null,
          error: "unknown",
          usage: NO_USAGE,
        }
      : { isAnswered: true, text: answer, usage: NO_USAGE };
  on("model.complete", (_$, e) => {
    seen.push(e.prompt);
    return { value: reply };
  });
};

test("with no key, the tool answers with the text of the fallback model", async ($: Engine, on: On) => {
  const seen: string[] = [];
  stub(on, seen, "yes");
  const { result } = await $.tool.call({
    tool: "mcp__dotclaude__second_opinion",
    question: "Use the cache?",
  });
  expect(String(result)).toContain("yes");
  expect(seen.length).toBe(1);
  expect(seen[0]).toContain("Use the cache?");
});

test("a fallback with no reply still asks the model once and does not throw", async ($: Engine, on: On) => {
  const seen: string[] = [];
  stub(on, seen, null);
  await $.tool.call({
    tool: "mcp__dotclaude__second_opinion",
    question: "Drop the table?",
  });
  expect(seen.length).toBe(1);
});

test("a call with no question sends no request to the model", async ($: Engine, on: On) => {
  const seen: string[] = [];
  stub(on, seen, "yes");
  await $.tool.call({ tool: "mcp__dotclaude__second_opinion", question: " " });
  expect(seen).toEqual([]);
});
